<?php /** @var array $o @var array $risks @var array $hist @var array $linkable */ $cls = $o['rag'] === 'green' ? 'ok' : ($o['rag'] === 'amber' ? 'warn' : 'danger'); ?>
<div class="page-head"><div><h1><?= icon('target') ?> <?= e($o['code']) ?> — <?= e($o['title']) ?></h1><p class="sub"><span class="badge islamic"><?= e(t('enum.persp.' . $o['perspective'])) ?></span> <span class="badge <?= $cls ?>"><?= (int)$o['progress'] ?>%</span><?= $o['late'] ? ' <span class="badge danger">' . e(t('my.overdue')) . '</span>' : '' ?></p></div>
  <div class="actions"><a class="btn secondary" href="<?= e(url('strategy')) ?>"><?= e(t('common.back')) ?></a><?php if (can('strategy.manage')): ?><a class="btn" href="<?= e(url('strategy/' . $o['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a>
  <form method="post" class="inline" action="<?= e(url('strategy/' . $o['id'] . '/archive')) ?>" data-confirm="<?= e(t('risk.confirm_archive')) ?>"><?= csrf_field() ?><button class="btn danger" type="submit"><?= e(t('common.archive')) ?></button></form><?php endif; ?></div></div>
<section class="card"><div class="meter big" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?= (int)$o['progress'] ?>"><span class="fill <?= e($o['rag']) ?>" style="width:<?= (int)$o['progress'] ?>%"></span></div>
<dl class="details" style="margin-top:12px"><dt><?= e(t('strat.owner')) ?></dt><dd><?= e($o['owner_name']) ?></dd><dt><?= e(t('strat.baseline')) ?></dt><dd><?= e(\App\Core\Money::plain($o['baseline']) . ' ' . $o['unit']) ?></dd><dt><?= e(t('strat.current_value')) ?></dt><dd><strong><?= e(\App\Core\Money::plain($o['current_value']) . ' ' . $o['unit']) ?></strong></dd><dt><?= e(t('strat.target')) ?></dt><dd><?= e(\App\Core\Money::plain($o['target']) . ' ' . $o['unit']) ?> (<?= e(t('enum.sdir.' . $o['direction'])) ?>)</dd><dt><?= e(t('strat.due_date')) ?></dt><dd><?= e(fdate($o['due_date'])) ?></dd><dt><?= e(t('strat.o_description')) ?></dt><dd class="pre"><?= e($o['description'] ?? '—') ?></dd></dl></section>
<?php if (can('strategy.manage')): ?><section class="card" id="update"><h2><?= e(t('strat.record')) ?></h2><form method="post" action="<?= e(url('strategy/' . $o['id'] . '/progress')) ?>" class="form-grid" novalidate><?= csrf_field() ?>
<?= ff('text', 'value', 'strat.value', '', ['required' => true, 'extra' => ' inputmode="decimal"']) ?><?= ff('text', 'note', 'strat.note', '') ?><div class="field"><button class="btn" type="submit"><?= e(t('common.save')) ?></button></div></form></section><?php endif; ?>
<div class="grid cols-2"><section class="card" id="risks"><h2><?= icon('alert') ?> <?= e(t('strat.risks')) ?></h2><p class="muted"><?= e(t('strat.risks_hint')) ?></p>
<ul class="task-list"><?php foreach ($risks as $r): ?><li><a href="<?= e(url('risks/' . $r['id'])) ?>"><?= e($r['risk_code'] . ' — ' . $r['title']) ?></a><span class="badge"><?= (int)$r['res_score'] ?></span>
<?php if (can('strategy.manage')): ?><form method="post" class="inline" action="<?= e(url('strategy/' . $o['id'] . '/risks/' . $r['id'] . '/remove')) ?>"><?= csrf_field() ?><button class="btn small danger" type="submit"><?= e(t('ctl.unlink')) ?></button></form><?php endif; ?></li><?php endforeach; ?></ul>
<?php if (!$risks): ?><p class="muted"><?= e(t('strat.no_risks')) ?></p><?php endif; ?>
<?php if ($linkable): ?><form method="post" action="<?= e(url('strategy/' . $o['id'] . '/risks')) ?>" class="filters"><?= csrf_field() ?><div class="field"><label for="risk_id"><?= e(t('ctl.link_risk')) ?></label><select id="risk_id" name="risk_id" required><option value=""><?= e(t('common.select')) ?></option><?php foreach ($linkable as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['risk_code'] . ' — ' . mb_strimwidth($r['title'], 0, 60, '…')) ?></option><?php endforeach; ?></select></div><div class="field"><button class="btn secondary" type="submit"><?= e(t('ctl.link')) ?></button></div></form><?php endif; ?></section>
<section class="card"><h2><?= e(t('strat.history')) ?></h2><?php if (!$hist): ?><p class="muted"><?= e(t('common.no_data')) ?></p><?php else: ?><ul class="task-list"><?php foreach ($hist as $h): ?><li><span><?= e(fdatetime($h['created_at'])) ?> — <?= e($h['full_name']) ?><?= $h['note'] ? ': ' . e($h['note']) : '' ?></span><strong><?= e(\App\Core\Money::plain($h['value'])) ?></strong></li><?php endforeach; ?></ul><?php endif; ?></section></div>
